#include "auto_animation/animation/MotionDatabase.hpp"
#include <algorithm>
#include <cmath>
#include <limits>
namespace auto_animation::animation{float motion_distance(const MotionFeature&a,const MotionFeature&b)noexcept{auto q=[](float x,float y){float z=x-y;return z*z;};return q(a.root_velocity.x,b.root_velocity.x)+q(a.root_velocity.y,b.root_velocity.y)+q(a.root_velocity.z,b.root_velocity.z)+.5f*(q(a.root_position.x,b.root_position.x)+q(a.root_position.y,b.root_position.y)+q(a.root_position.z,b.root_position.z))+.1f*q(a.pose_energy,b.pose_energy);}void MotionDatabase::clear(){f_.clear();r_.clear();}void MotionDatabase::add_clip(const AnimationClip&c,float rate){if(rate<=0)return;Pose bind;std::size_t max_index=0;bool has_index=false;for(const auto&t:c.tracks)if(t.bone_index>=0){max_index=std::max(max_index,(std::size_t)t.bone_index);has_index=true;}if(has_index)bind.local_transforms.resize(max_index+1);std::size_t clip_id=0;for(const auto&x:r_)clip_id=std::max(clip_id,x.clip+1);int n=(int)(c.duration_seconds*rate)+1;for(int i=0;i<n;++i){double t=std::min(c.duration_seconds,static_cast<double>(i)/static_cast<double>(rate));auto p=sample_clip(c,t,bind);MotionFeature x;x.time=t;if(!p.local_transforms.empty())x.root_position=p.local_transforms[0].translation;if(i>0){auto prev=f_.back();float dt=(float)(t-prev.time);if(dt>0)x.root_velocity={(x.root_position.x-prev.root_position.x)/dt,(x.root_position.y-prev.root_position.y)/dt,(x.root_position.z-prev.root_position.z)/dt};}for(auto&tr:p.local_transforms)x.pose_energy+=std::fabs(tr.translation.x)+std::fabs(tr.translation.y)+std::fabs(tr.translation.z);r_.push_back({clip_id,f_.size(),0});f_.push_back(x);}}MotionSampleRef MotionDatabase::query(const MotionFeature&d)const{MotionSampleRef b{};b.distance=std::numeric_limits<float>::max();for(auto x:r_){float z=motion_distance(f_[x.feature],d);if(z<b.distance){b=x;b.distance=z;}}return b;}}